def est(e,pct=False):
 if e['value'] is None:return 'N/A'
 factor=100 if pct else 1; unit='%' if pct else '';lo,hi=e['ci95'];return f"{e['value']*factor:.2f}{unit} [{lo*factor:.2f}, {hi*factor:.2f}]"
